use std::collections::{BTreeMap, HashSet};
use std::fs;
use std::io::{self, BufRead};
use std::net::{IpAddr, Ipv4Addr, Ipv6Addr};
use std::path::Path;
use std::str::FromStr;

mod config;
mod parser;
mod output;

use config::Config;
use parser::Parser;
use output::Output;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut parser = Parser::new();

    // Parse command line arguments
    match parser.parse(&args[1..]) {
        Ok(config) => {
            // Check for special modes
            if config.show_help {
                print_help();
                std::process::exit(if config.version_shown { 1 } else { 0 });
            }

            if config.show_version {
                print_version();
                std::process::exit(1);
            }

            if config.show_nmap_help {
                print_nmap_help();
                std::process::exit(1);
            }

            if config.show_iflist {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("libpcap not loaded");
                std::process::exit(0);
            }

            // Check for errors
            if !config.ports.is_empty() || config.echo {
                // Validation only happens if we're actually scanning or echoing with ports
                if config.ports.is_empty() && !config.targets.is_empty() {
                    eprintln!("[-] FAIL: failed to load libpcap shared library");
                    eprintln!("    [hint]: you must install libpcap or WinPcap");
                    eprintln!("FAIL: no ports were specified");
                    eprintln!(" [hint] try something like \"-p80,8000-9000\"");
                    eprintln!(" [hint] try something like \"--ports 0-65535\"");
                    std::process::exit(1);
                }

                if config.targets.is_empty() && config.ports.is_empty() {
                    eprintln!("[-] FAIL: failed to load libpcap shared library");
                    eprintln!("    [hint]: you must install libpcap or WinPcap");
                    eprintln!("FAIL: target IP address list empty");
                    eprintln!(" [hint] try something like \"--range 10.0.0.0/8\"");
                    eprintln!(" [hint] try something like \"--range 192.168.0.100-192.168.0.200\"");
                    std::process::exit(1);
                }
            } else if !config.targets.is_empty() && config.ports.is_empty() {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("FAIL: no ports were specified");
                eprintln!(" [hint] try something like \"-p80,8000-9000\"");
                eprintln!(" [hint] try something like \"--ports 0-65535\"");
                std::process::exit(1);
            }

            // Print libpcap warning if echo mode
            if config.echo {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
            }

            // Generate echo output
            if config.echo {
                let output = Output::new(&config);
                println!("{}", output.generate_echo());
                std::process::exit(0);
            }

            // Normal operation would continue here (not implemented for this minimal version)
            eprintln!("[-] FAIL: failed to load libpcap shared library");
            eprintln!("    [hint]: you must install libpcap or WinPcap");
            eprintln!("FAIL:eth0: can't open adapter: libpcap not loaded");
            eprintln!("[-] if:eth0:init: failed");
            std::process::exit(1);
        }
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

fn print_help() {
    println!("usage: masscan [options] [<IP|RANGE>... -pPORT[,PORT...]]");
    println!("MASSCAN is a fast port scanner. The primary input parameters are the");
    println!("IP addresses/ranges you want to scan, and the port numbers. An example");
    println!("is the following, which scans the 10.x.x.x network for web servers:");
    println!();
    println!("    masscan 10.0.0.0/8 -p80");
    println!();
    println!("The program auto-detects network interface/adapter settings. If this");
    println!("fails, you'll have to set these manually. The following is an");
    println!("example of all the parameters that are needed:");
    println!();
    println!("    --adapter-ip 192.168.10.123");
    println!("    --adapter-mac 00-11-22-33-44-55");
    println!("    --router-mac 66-55-44-33-22-11");
    println!();
    println!("Parameters can be set either via the command-line or config-file. The");
    println!("names are the same for both. Thus, the above adapter settings would");
    println!("appear as follows in a configuration file:");
    println!();
    println!("    adapter-ip = 192.168.10.123");
    println!("    adapter-mac = 00-11-22-33-44-55");
    println!("    router-mac = 66-55-44-33-22-11");
    println!();
    println!("All single-dash parameters have a spelled out double-dash equivalent,");
    println!("so '-p80' is the same as '--ports 80' (or 'ports = 80' in config file).");
    println!("To use the config file, type:");
    println!();
    println!("    masscan -c <filename>");
    println!();
    println!("To generate a config-file from the current settings, use the --echo");
    println!("option. This stops the program from actually running, and just echoes");
    println!("the current configuration instead. This is a useful way to generate");
    println!("your first config file, or see a list of parameters you didn't know");
    println!("about. I suggest you try it now:");
    println!();
    println!("    masscan -p1234 --echo");
}

fn print_version() {
    println!();
    println!("Masscan version 1.3.9-integration ( https://github.com/robertdavidgraham/masscan )");
    println!("Compiled on: Apr 17 2026 19:59:25");
    println!("Compiler: gcc 11.4.0");
    println!("OS: Linux");
    println!("CPU: x86 (64 bits)");
    println!("GIT version: unknown");
}

fn print_nmap_help() {
    println!("Masscan (https://github.com/robertdavidgraham/masscan)");
    println!("Usage: masscan [Options] -p{{Target-Ports}} {{Target-IP-Ranges}}");
    println!("TARGET SPECIFICATION:");
    println!("  Can pass only IPv4/IPv6 address, CIDR networks, or ranges (non-nmap style)");
    println!("  Ex: 10.0.0.0/8, 192.168.0.1, 10.0.0.1-10.0.0.254");
    println!("  -iL <inputfilename>: Input from list of hosts/networks");
    println!("  --exclude <host1[,host2][,host3],...>: Exclude hosts/networks");
    println!("  --excludefile <exclude_file>: Exclude list from file");
    println!("  --randomize-hosts: Randomize order of hosts (default)");
    println!("HOST DISCOVERY:");
    println!("  -Pn: Treat all hosts as online (default)");
    println!("  -n: Never do DNS resolution (default)");
    println!("SCAN TECHNIQUES:");
    println!("  -sS: TCP SYN (always on, default)");
    println!("SERVICE/VERSION DETECTION:");
    println!("  --banners: get the banners of the listening service if available. The");
    println!("    default timeout for waiting to receive data is 30 seconds.");
    println!("PORT SPECIFICATION AND SCAN ORDER:");
    println!("  -p <port ranges>: Only scan specified ports");
    println!("    Ex: -p22; -p1-65535; -p 111,137,80,139,8080");
    println!("TIMING AND PERFORMANCE:");
    println!("  --max-rate <number>: Send packets no faster than <number> per second");
    println!("  --connection-timeout <number>: time in seconds a TCP connection will");
    println!("    timeout while waiting for banner data from a port.");
    println!("FIREWALL/IDS EVASION AND SPOOFING:");
    println!("  -S/--source-ip <IP_Address>: Spoof source address");
    println!("  -e <iface>: Use specified interface");
    println!("  -g/--source-port <portnum>: Use given port number");
    println!("  --ttl <val>: Set IP time-to-live field");
    println!("  --spoof-mac <mac address/prefix/vendor name>: Spoof your MAC address");
    println!("OUTPUT:");
    println!("  --output-format <format>: Sets output to binary/list/unicornscan/json/ndjson/grepable/xml");
    println!("  --output-file <file>: Write scan results to file. If --output-format is");
    println!("     not given default is xml");
    println!("  -oL/-oJ/-oD/-oG/-oB/-oX/-oU <file>: Output scan in List/JSON/nDjson/Grepable/Binary/XML/Unicornscan format,");
    println!("     respectively, to the given filename. Shortcut for");
    println!("     --output-format <format> --output-file <file>");
    println!("  -v: Increase verbosity level (use -vv or more for greater effect)");
    println!("  -d: Increase debugging level (use -dd or more for greater effect)");
    println!("  --open: Only show open (or possibly open) ports");
    println!("  --packet-trace: Show all packets sent and received");
    println!("  --iflist: Print host interfaces and routes (for debugging)");
    println!("  --append-output: Append to rather than clobber specified output files");
    println!("  --resume <filename>: Resume an aborted scan");
    println!("MISC:");
    println!("  --send-eth: Send using raw ethernet frames (default)");
    println!("  -V: Print version number");
    println!("  -h: Print this help summary page.");
    println!("EXAMPLES:");
    println!("  masscan -v -sS 192.168.0.0/16 10.0.0.0/8 -p 80");
    println!("  masscan 23.0.0.0/0 -p80 --banners -output-format binary --output-filename internet.scan");
    println!("  masscan --open --banners --readscan internet.scan -oG internet_scan.grepable");
    println!("SEE (https://github.com/robertdavidgraham/masscan) FOR MORE HELP");
}
