pub struct Parser;

impl Parser {
    pub fn new() -> Self {
        Parser
    }

    pub fn parse(&mut self, args: &[String]) -> Result<Config, String> {
        let mut config = Config::default();
        let mut i = 0;

        while i < args.len() {
            let arg = &args[i];

            if arg == "-h" || arg == "--help" {
                config.show_help = true;
                return Ok(config);
            } else if arg == "-V" || arg == "--version" {
                config.show_version = true;
                config.version_shown = true;
                return Ok(config);
            } else if arg == "--nmap" {
                config.show_nmap_help = true;
                return Ok(config);
            } else if arg == "--iflist" {
                config.show_iflist = true;
                return Ok(config);
            } else if arg == "--echo" {
                config.echo = true;
            } else if arg == "-p" || arg == "--ports" {
                i += 1;
                if i >= args.len() {
                    return Err("port specification missing".to_string());
