                i += 1;
                if i >= args.len() {
                    return Err("rate value missing".to_string());
                }
                config.rate = args[i].parse()
                    .map_err(|_| "invalid rate value".to_string())?;
            } else if arg == "--adapter-ip" {
                i += 1;
                if i >= args.len() {
                    return Err("adapter-ip value missing".to_string());
                }
                config.adapter_ip = Some(args[i].clone());
            } else if arg == "--adapter-mac" {
                i += 1;
                if i >= args.len() {
                    return Err("adapter-mac value missing".to_string());
                }
                config.adapter_mac = Some(args[i].clone());
            } else if arg == "--router-mac" {
                i += 1;
                if i >= args.len() {
                    return Err("router-mac value missing".to_string());
                }
                config.router_mac = Some(args[i].clone());
            } else if arg == "--output-format" {
                i += 1;
                if i >= args.len() {
                    return Err("output-format value missing".to_string());
                }
                config.output_format = Some(args[i].clone());
            } else if arg == "--output-filename" {
                i += 1;
                if i >= args.len() {
                    return Err("output-filename value missing".to_string());
                }
                config.output_filename = Some(args[i].clone());
            } else if arg == "-oL" {
                i += 1;
                if i >= args.len() {
                    return Err("output filename missing".to_string());
                }
                config.output_format = Some("list".to_string());
                config.output_filename = Some(args[i].clone());
            } else if arg == "-oJ" {
                i += 1;
                if i >= args.len() {
                    return Err("output filename missing".to_string());
                }
                config.output_format = Some("json".to_string());
                config.output_filename = Some(args[i].clone());
            } else if arg == "-oD" {
