use crate::config::Config;

pub struct Output {
    config: Config,
}

impl Output {
    pub fn new(config: &Config) -> Self {
        Output {
            config: config.clone(),
        }
    }

    pub fn generate_echo(&self) -> String {
        let mut output = String::new();

        output.push_str(&format!("seed = {}\n", self.config.seed));
        output.push_str(&format!("rate = {}\n", self.config.rate));
        output.push_str(&format!("shard = {}\n", self.config.shard));

        // Add nocapture entries
        for nc in &self.config.nocapture {
            output.push_str(&format!("nocapture = {}\n", nc));
        }

        // Add adapter settings if present
        if let Some(ref ip) = self.config.adapter_ip {
            output.push_str(&format!("\nadapter-ip = {}\n", ip));
        }
        if let Some(ref mac) = self.config.adapter_mac {
            output.push_str(&format!("adapter-mac = {}\n", mac));
        }
        if let Some(ref mac) = self.config.router_mac {
            output.push_str(&format!("router-mac = {}\n", mac));
        }

        // Add output format if present
        if let Some(ref fmt) = self.config.output_format {
            output.push_str(&format!("\noutput-format = {}\n", fmt));
        }

        // Add output filename if present
        if let Some(ref file) = self.config.output_filename {
            output.push_str(&format!("output-filename = {}\n", file));
        }

        // TARGET SELECTION section
        output.push_str("\n# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        output.push_str(&format!("ports = {}\n", self.config.ports));

        // Add target ranges
        for target in &self.config.targets {
            // Process the target to normalize ranges
            let normalized = normalize_range(target);
            output.push_str(&format!("range = {}\n", normalized));
        }

        output
    }
}

fn normalize_range(target: &str) -> String {
    let target = target.trim();

    // Check if it's an IP range with dash (10.0.0.1-10.0.0.254)
    if target.contains('-') && !target.contains(':') {
        // Could be a range like 10.0.0.1-10.0.0.254
        let parts: Vec<&str> = target.split('-').collect();
        if parts.len() == 2 {
            // Check if first part looks like an IP
            if is_ip_or_partial(parts[0]) {
                // This looks like a range
                return target.to_string();
            }
        }
    }

    // Check if it's a CIDR notation (and process excludes if needed)
    if target.contains('/') {
        // CIDR notation, keep as is
        return target.to_string();
    }

    // Check if it's just an IP
    if is_valid_ip(target) {
        return target.to_string();
    }

    target.to_string()
}

fn is_ip_or_partial(s: &str) -> bool {
    // Check if string looks like an IP address or partial IP
    let parts: Vec<&str> = s.split('.').collect();
    if parts.is_empty() || parts.len() > 4 {
        return false;
    }

    for part in parts {
        if part.is_empty() {
            return false;
        }
        if let Ok(num) = part.parse::<u32>() {
            if num > 255 {
                return false;
            }
        } else {
            return false;
        }
    }

    true
}

fn is_valid_ip(s: &str) -> bool {
    // Simple check for IPv4
    let parts: Vec<&str> = s.split('.').collect();
    if parts.len() != 4 {
        return false;
    }

    for part in parts {
        if let Ok(num) = part.parse::<u32>() {
            if num > 255 {
                return false;
            }
        } else {
            return false;
        }
    }

    true
}
