mod config;
mod parser;
mod output;

use config::Config;
use parser::Parser;
use output::Output;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut parser = Parser::new();

    // Parse command line arguments
    match parser.parse(&args[1..]) {
        Ok(config) => {
            // Check for special modes
            if config.show_help {
                print_help();
                std::process::exit(if config.version_shown { 1 } else { 0 });
            }

            if config.show_version {
                print_version();
                std::process::exit(1);
            }

            if config.show_nmap_help {
                print_nmap_help();
                std::process::exit(1);
            }

            if config.show_iflist {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("libpcap not loaded");
                std::process::exit(0);
            }

            // Check for errors
            if !config.ports.is_empty() || config.echo {
                // Validation only happens if we're actually scanning or echoing with ports
                if config.ports.is_empty() && !config.targets.is_empty() {
                    eprintln!("[-] FAIL: failed to load libpcap shared library");
                    eprintln!("    [hint]: you must install libpcap or WinPcap");
                    eprintln!("FAIL: no ports were specified");
                    eprintln!(" [hint] try something like \"-p80,8000-9000\"");
                    eprintln!(" [hint] try something like \"--ports 0-65535\"");
                    std::process::exit(1);
                }

