        use std::time::{SystemTime, UNIX_EPOCH};

        match SystemTime::now().duration_since(UNIX_EPOCH) {
            Ok(duration) => {
                let nanos = duration.subsec_nanos() as u64;
                let secs = duration.as_secs();
                (secs ^ nanos) | (nanos << 32)
            }
            Err(_) => 12345,
        }
    }
}
