                config.output_format = Some("xml".to_string());
                config.output_filename = Some(args[i].clone());
            } else if arg == "-oU" {
                i += 1;
                if i >= args.len() {
                    return Err("output filename missing".to_string());
                }
                config.output_format = Some("unicornscan".to_string());
                config.output_filename = Some(args[i].clone());
            } else if arg == "--exclude" {
                i += 1;
                if i >= args.len() {
                    return Err("exclude value missing".to_string());
                }
                config.excludes = args[i].split(',').map(|s| s.to_string()).collect();
            } else if arg == "--exclude-file" || arg == "--excludefile" {
                i += 1;
                if i >= args.len() {
                    return Err("excludefile value missing".to_string());
                }
                self.parse_exclude_file(&args[i], &mut config)?;
            } else if arg.starts_with("-") {
                // Unknown flag - for now, skip value if it looks like it takes one
                if arg.starts_with("--") && arg.contains("=") {
                    // Handle --key=value format
                    let parts: Vec<&str> = arg.splitn(2, '=').collect();
                    if parts.len() == 2 {
                        self.handle_key_value(parts[0].trim_start_matches("--"), parts[1], &mut config)?;
                    }
                } else if i + 1 < args.len() && !args[i + 1].starts_with("-") {
                    // Skip the next argument as it might be a value
                    i += 1;
                }
            } else {
                // This is a positional argument (target IP/range)
                config.targets.push(arg.clone());
            }

            i += 1;
        }

        Ok(config)
    }

    fn handle_key_value(&self, key: &str, value: &str, config: &mut Config) -> Result<(), String> {
        match key {
            "adapter-ip" => config.adapter_ip = Some(value.to_string()),
            "adapter-mac" => config.adapter_mac = Some(value.to_string()),
            "router-mac" => config.router_mac = Some(value.to_string()),
            "output-format" => config.output_format = Some(value.to_string()),
            "output-filename" => config.output_filename = Some(value.to_string()),
            "seed" => config.seed = value.parse().map_err(|_| "invalid seed".to_string())?,
            "rate" => config.rate = value.parse().map_err(|_| "invalid rate".to_string())?,
            _ => {}
        }
        Ok(())
    }

    fn parse_config_file(&self, path: &str, config: &mut Config) -> Result<(), String> {
        let content = fs::read_to_string(path)
            .map_err(|e| format!("failed to read config file: {}", e))?;

        for line in content.lines() {
            let line = line.trim();

            // Skip comments and empty lines
            if line.starts_with('#') || line.is_empty() {
                continue;
            }

            // Parse key = value format
            if let Some(eq_idx) = line.find('=') {
                let key = line[..eq_idx].trim();
                let value = line[eq_idx + 1..].trim().trim_matches('"').trim_matches('\'');

                match key {
                    "ports" => config.ports = value.to_string(),
                    "range" => config.targets.push(value.to_string()),
                    "exclude" => {
                        config.excludes = value.split(',').map(|s| s.to_string()).collect();
                    }
                    "seed" => config.seed = value.parse().map_err(|_| "invalid seed".to_string())?,
                    "rate" => config.rate = value.parse().map_err(|_| "invalid rate".to_string())?,
                    "adapter-ip" => config.adapter_ip = Some(value.to_string()),
                    "adapter-mac" => config.adapter_mac = Some(value.to_string()),
                    "router-mac" => config.router_mac = Some(value.to_string()),
                    "output-format" => config.output_format = Some(value.to_string()),
                    "output-filename" => config.output_filename = Some(value.to_string()),
                    "nocapture" => config.nocapture.push(value.to_string()),
                    _ => {}
                }
            }
        }

        Ok(())
    }

    fn parse_exclude_file(&self, path: &str, config: &mut Config) -> Result<(), String> {
        let content = fs::read_to_string(path)
            .map_err(|e| format!("failed to read exclude file: {}", e))?;

        for line in content.lines() {
            let line = line.trim();
            if !line.is_empty() && !line.starts_with('#') {
                config.excludes.push(line.to_string());
            }
        }

        Ok(())
    }
}
