                    let result_ranges = if exclude_ranges.is_empty() {
                        vec![range]
                    } else {
                        range.subtract(&exclude_ranges)
                    };

                    for result_range in result_ranges {
                        output.push_str(&format!("range = {}\n", result_range.to_string()));
                    }
                }
            }
        }

        output
    }
}
