use parser::Parser;
use output::Output;

fn main() {
    let args: Vec<String> = std::env::args().collect();

    let mut parser = Parser::new();

    // Parse command line arguments
    match parser.parse(&args[1..]) {
        Ok(config) => {
            // Check for special modes
            if config.show_help {
                print_help();
                std::process::exit(if config.version_shown { 1 } else { 0 });
            }

            if config.show_version {
                print_version();
                std::process::exit(1);
            }

            if config.show_nmap_help {
                print_nmap_help();
                std::process::exit(1);
            }

            if config.show_iflist {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("libpcap not loaded");
                std::process::exit(0);
            }

            // Validation: targets must be specified along with ports
            if config.targets.is_empty() && config.ports.is_empty() {
                // Both missing
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("FAIL: target IP address list empty");
                eprintln!(" [hint] try something like \"--range 10.0.0.0/8\"");
                eprintln!(" [hint] try something like \"--range 192.168.0.100-192.168.0.200\"");
                std::process::exit(1);
            }

            // Validation: targets but no ports
            if !config.targets.is_empty() && config.ports.is_empty() {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("FAIL: no ports were specified");
                eprintln!(" [hint] try something like \"-p80,8000-9000\"");
                eprintln!(" [hint] try something like \"--ports 0-65535\"");
                std::process::exit(1);
            }

            // Validation: ports but no targets (different message than both missing)
            if config.targets.is_empty() && !config.ports.is_empty() {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
                eprintln!("FAIL: target IP address list empty");
                eprintln!(" [hint] try something like \"--range 10.0.0.0/8\"");
                eprintln!(" [hint] try something like \"--range 192.168.0.100-192.168.0.200\"");
                std::process::exit(1);
            }

            // Print libpcap warning if echo mode
            if config.echo {
                eprintln!("[-] FAIL: failed to load libpcap shared library");
                eprintln!("    [hint]: you must install libpcap or WinPcap");
            }

            // Generate echo output
            if config.echo {
                let output = Output::new(&config);
                println!("{}", output.generate_echo());
                std::process::exit(0);
            }

            // Normal operation would continue here (not implemented for this minimal version)
            eprintln!("[-] FAIL: failed to load libpcap shared library");
            eprintln!("    [hint]: you must install libpcap or WinPcap");
            eprintln!("FAIL:eth0: can't open adapter: libpcap not loaded");
            eprintln!("[-] if:eth0:init: failed");
            std::process::exit(1);
        }
        Err(e) => {
            eprintln!("{}", e);
            std::process::exit(1);
        }
    }
}

fn print_help() {
