use crate::config::Config;

pub struct Output {
    config: Config,
}

#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
struct Ipv4 {
    parts: [u8; 4],
}

impl Ipv4 {
    fn from_str(s: &str) -> Option<Self> {
        let parts: Vec<&str> = s.split('.').collect();
        if parts.len() != 4 {
            return None;
        }
        let mut ip = [0u8; 4];
        for (i, part) in parts.iter().enumerate() {
            ip[i] = part.parse().ok()?;
        }
        Some(Ipv4 { parts: ip })
    }

    fn to_u32(&self) -> u32 {
        ((self.parts[0] as u32) << 24)
            | ((self.parts[1] as u32) << 16)
            | ((self.parts[2] as u32) << 8)
            | (self.parts[3] as u32)
    }

    fn from_u32(val: u32) -> Self {
        Ipv4 {
            parts: [
                ((val >> 24) & 0xFF) as u8,
                ((val >> 16) & 0xFF) as u8,
                ((val >> 8) & 0xFF) as u8,
                (val & 0xFF) as u8,
            ],
        }
    }

    fn to_string(&self) -> String {
        format!(
            "{}.{}.{}.{}",
            self.parts[0], self.parts[1], self.parts[2], self.parts[3]
        )
    }
}

struct IpRange {
    start: Ipv4,
    end: Ipv4,
}

impl IpRange {
    fn from_cidr(cidr: &str) -> Option<(Self, String)> {
        let parts: Vec<&str> = cidr.split('/').collect();
        if parts.len() != 2 {
            return None;
        }

        let ip = Ipv4::from_str(parts[0])?;
        let prefix_len: u32 = parts[1].parse().ok()?;

        if prefix_len > 32 {
            return None;
        }

        let mask = if prefix_len == 0 {
            0
        } else {
            0xFFFFFFFF << (32 - prefix_len)
        };

        let start_u32 = ip.to_u32() & mask;
        let end_u32 = start_u32 | (!mask);

        Some((
            IpRange {
                start: Ipv4::from_u32(start_u32),
                end: Ipv4::from_u32(end_u32),
            },
            cidr.to_string(), // Return original format
        ))
    }

    fn from_range(s: &str) -> Option<(Self, String)> {
        let parts: Vec<&str> = s.split('-').collect();
        if parts.len() != 2 {
            return None;
        }

        let start = Ipv4::from_str(parts[0])?;
        let end = Ipv4::from_str(parts[1])?;

        Some((
            IpRange { start, end },
            s.to_string(), // Return original format
        ))
    }

    fn from_ip(s: &str) -> Option<(Self, String)> {
        let ip = Ipv4::from_str(s)?;
        Some((
            IpRange { start: ip, end: ip },
            s.to_string(), // Return original format
        ))
    }

    fn parse(s: &str) -> Option<(Vec<IpRange>, Vec<String>)> {
        if s.contains('/') {
            // CIDR notation
            IpRange::from_cidr(s).map(|(r, fmt)| (vec![r], vec![fmt]))
        } else if s.contains('-') {
            // Range notation
            IpRange::from_range(s).map(|(r, fmt)| (vec![r], vec![fmt]))
        } else {
            // Single IP
            IpRange::from_ip(s).map(|(r, fmt)| (vec![r], vec![fmt]))
        }
    }

    fn overlaps_with(&self, other: &IpRange) -> bool {
        self.start <= other.end && self.end >= other.start
    }

    fn subtract(&self, excludes: &[IpRange]) -> Vec<IpRange> {
        let mut result = vec![self.clone()];

        for exclude in excludes {
            let mut new_result = Vec::new();
            for range in result {
                new_result.extend(range.subtract_single(exclude));
            }
            result = new_result;
        }

        result
    }

    fn subtract_single(&self, exclude: &IpRange) -> Vec<IpRange> {
        if !self.overlaps_with(exclude) {
            // No overlap
            return vec![self.clone()];
        }

        let mut result = Vec::new();

        // Add the part before the exclusion
        if self.start < exclude.start {
            result.push(IpRange {
                start: self.start,
                end: Ipv4::from_u32(exclude.start.to_u32().saturating_sub(1)),
            });
        }

        // Add the part after the exclusion
        if self.end > exclude.end {
            result.push(IpRange {
                start: Ipv4::from_u32(exclude.end.to_u32().saturating_add(1)),
                end: self.end,
            });
        }

        result
    }

    fn to_string(&self) -> String {
        if self.start == self.end {
            self.start.to_string()
        } else {
            format!("{}-{}", self.start.to_string(), self.end.to_string())
        }
    }
}

impl Clone for IpRange {
    fn clone(&self) -> Self {
        IpRange {
            start: self.start,
            end: self.end,
        }
    }
}

impl Output {
    pub fn new(config: &Config) -> Self {
        Output {
            config: config.clone(),
        }
    }

    pub fn generate_echo(&self) -> String {
        let mut output = String::new();

        output.push_str(&format!("seed = {}\n", self.config.seed));
        // rate line has exactly 7 trailing spaces
        output.push_str(&format!("rate = {}       \n", self.config.rate));
        output.push_str(&format!("shard = {}\n", self.config.shard));

        // Add nocapture entries
        for nc in &self.config.nocapture {
            output.push_str(&format!("nocapture = {}\n", nc));
        }

        // Add adapter settings if present
        if let Some(ref ip) = self.config.adapter_ip {
            output.push_str(&format!("\nadapter-ip = {}\n", ip));
        }
        if let Some(ref mac) = self.config.adapter_mac {
            output.push_str(&format!("adapter-mac = {}\n", mac));
        }
        if let Some(ref mac) = self.config.router_mac {
            output.push_str(&format!("router-mac = {}\n", mac));
        }

        // Add output format if present
        if let Some(ref fmt) = self.config.output_format {
            output.push_str(&format!("\noutput-format = {}\n", fmt));
        }

        // Add output filename if present
        if let Some(ref file) = self.config.output_filename {
            output.push_str(&format!("output-filename = {}\n", file));
        }

        // TARGET SELECTION section
        output.push_str("\n# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        output.push_str(&format!("ports = {}\n", self.config.ports));

        // Parse excludes
        let mut exclude_ranges = Vec::new();
        for exclude in &self.config.excludes {
            if let Some((ranges, _)) = IpRange::parse(exclude) {
                exclude_ranges.extend(ranges);
            }
        }

        // Add target ranges, with exclusions applied
        for target in &self.config.targets {
            if let Some((target_ranges, target_format)) = IpRange::parse(target) {
                // If we have exclusions, we need to compute new ranges
                if !exclude_ranges.is_empty() {
                    for range in target_ranges {
                        let result_ranges = range.subtract(&exclude_ranges);
                        for result_range in result_ranges {
                            output.push_str(&format!("range = {}\n", result_range.to_string()));
                        }
                    }
                } else {
                    // No exclusions, preserve original format
                    for fmt in target_format {
                        output.push_str(&format!("range = {}\n", fmt));
                    }
                }
            }
        }

        output
    }
}
