        output.push_str(&format!("seed = {}\n", self.config.seed));
        // rate line formatting depends on the rate value
        output.push_str(&format!("rate = {}\n", format_rate(self.config.rate)));
        output.push_str(&format!("shard = {}\n", self.config.shard));

        // Add nocapture entries
        for nc in &self.config.nocapture {
            output.push_str(&format!("nocapture = {}\n", nc));
        }

        // Determine if we have any adapter settings or output formats
        let has_adapter_only = 
            (self.config.adapter_ip.is_some() || 
             self.config.adapter_mac.is_some() || 
             self.config.router_mac.is_some()) &&
            self.config.output_format.is_none() &&
            self.config.output_filename.is_none();

