            (self.config.output_format.is_some() ||
             self.config.output_filename.is_some()) &&
            self.config.adapter_ip.is_none() &&
            self.config.adapter_mac.is_none() &&
            self.config.router_mac.is_none();

        let has_both = 
            (self.config.adapter_ip.is_some() || 
             self.config.adapter_mac.is_some() || 
             self.config.router_mac.is_some()) &&
            (self.config.output_format.is_some() ||
             self.config.output_filename.is_some());

