        for nc in &self.config.nocapture {
            output.push_str(&format!("nocapture = {}\n", nc));
        }

        // Determine what adapter/output settings we have
        let has_adapter_ip = self.config.adapter_ip.is_some();
        let has_adapter_mac = self.config.adapter_mac.is_some();
        let has_router_mac = self.config.router_mac.is_some();
        let has_output_format = self.config.output_format.is_some();
        let has_output_filename = self.config.output_filename.is_some();

        let has_any_adapter = has_adapter_ip || has_adapter_mac || has_router_mac;
        let has_any_output = has_output_format || has_output_filename;

        if has_any_adapter {
            output.push_str("\n\n");
            if has_adapter_ip {
                output.push_str(&format!("adapter-ip = {}\n", self.config.adapter_ip.as_ref().unwrap()));
            }
            if has_adapter_mac {
                output.push_str(&format!("adapter-mac = {}\n", self.config.adapter_mac.as_ref().unwrap()));
            }
            if has_router_mac {
                output.push_str(&format!("router-mac = {}\n", self.config.router_mac.as_ref().unwrap()));
            }
        }

        if has_any_output {
            if !has_any_adapter {
                output.push_str("\n");
            } else {
                output.push_str("\n");
            }
            if has_output_format {
                output.push_str(&format!("output-format = {}\n", self.config.output_format.as_ref().unwrap()));
            }
            if has_output_filename {
                output.push_str(&format!("output-filename = {}\n", self.config.output_filename.as_ref().unwrap()));
            }
        }

        // TARGET SELECTION section
        if !has_any_adapter && !has_any_output {
            // No adapter or output settings, add double newline
            output.push_str("\n\n");
        } else if has_any_output {
            // Has output settings - add a blank line before TARGET
            output.push_str("\n");
        }
        // else: has_any_adapter but no output - just put TARGET directly (no extra newline)

        output.push_str("# TARGET SELECTION (IP, PORTS, EXCLUDES)\n");
        output.push_str(&format!("ports = {}\n", self.config.ports));

        // Parse excludes
        let mut exclude_ranges = Vec::new();
        for exclude in &self.config.excludes {
            if let Some((ranges, _)) = IpRange::parse(exclude) {
                exclude_ranges.extend(ranges);
            }
        }

        // Add target ranges, with exclusions applied
        for target in &self.config.targets {
            if let Some((target_ranges, target_format)) = IpRange::parse(target) {
                // If we have exclusions, we need to compute new ranges
                if !exclude_ranges.is_empty() {
                    for range in target_ranges {
                        let result_ranges = range.subtract(&exclude_ranges);
                        for result_range in result_ranges {
                            output.push_str(&format!("range = {}\n", result_range.to_string()));
                        }
                    }
                } else {
                    // No exclusions, preserve original format
                    for fmt in target_format {
                        output.push_str(&format!("range = {}\n", fmt));
                    }
                }
            }
        }

        output
    }
}
